---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedCreativeFormatEnum "CREATIVE_FORMAT_UNSPECIFIED"|"CREATIVE_FORMAT_DISPLAY"|"CREATIVE_FORMAT_VIDEO"|"CREATIVE_FORMAT_AUDIO"

---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedDeviceTypesItemEnum "DEVICE_TYPE_UNSPECIFIED"|"DEVICE_TYPE_PERSONAL_COMPUTER"|"DEVICE_TYPE_CONNECTED_TV"|"DEVICE_TYPE_PHONE"|"DEVICE_TYPE_TABLET"

