---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedNativeInventoryTypesItemEnumList (gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedNativeInventoryTypesItemEnum|string)[]

---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedOpenMeasurementTypesItemEnum "OPEN_MEASUREMENT_TYPE_UNSPECIFIED"|"OPEN_MEASUREMENT_TYPE_OMID_V1"

---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedOpenMeasurementTypesItemEnumList (gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedOpenMeasurementTypesItemEnum|string)[]

---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageTargetingIncludedRestrictedCategoriesItemEnum "RESTRICTED_CATEGORY_UNSPECIFIED"|"RESTRICTED_CATEGORY_ALCOHOL"|"RESTRICTED_CATEGORY_GAMBLING"

