---@alias gcp.unstable.authorizedbuyersmarketplace_v1alpha.PackageVideoTargetingIncludedMaximumAdDurationTargetingEnum "MAXIMUM_VIDEO_AD_DURATION_UNSPECIFIED"|"MAXIMUM_VIDEO_AD_DURATION_FIFTEEN_SECONDS"|"MAXIMUM_VIDEO_AD_DURATION_TWENTY_SECONDS"|"MAXIMUM_VIDEO_AD_DURATION_THIRTY_SECONDS"|"MAXIMUM_VIDEO_AD_DURATION_SIXTY_SECONDS"|"MAXIMUM_VIDEO_AD_DURATION_NINETY_SECONDS"|"MAXIMUM_VIDEO_AD_DURATION_ONE_HUNDRED_TWENTY_SECONDS"

